+        status.textContent = "Please review the highlighted fields and try again.";
+        invalidFields[0].focus();
+        return;
+      }
+
+      event.preventDefault();
+      status.textContent = "Thanks. Your support request is ready to send.";
+      form.reset();
+      fields.forEach(({ id }) => setFieldError(getFieldById(id), ""));
+      getFieldById("fullName").focus();
+    });
+
+    fields.forEach(({ id }) => {
+      const field = getFieldById(id);
+      field.addEventListener("blur", () => {
+        if (submissionAttempted) {
+          validateField(field);
+        }
+      });
+      field.addEventListener("input", () => {
+        if (submissionAttempted) {
+          validateField(field);
+        }
+      });
+    });
+  </script>
