<body>
  <div id="app"></div>

  <script>
    const fields = [
      {
        id: "fullName",
        name: "fullName",
        label: "Full name",
        type: "text",
        autocomplete: "name",
        required: true,
        placeholder: "Jordan Lee"
      },
      {
        id: "email",
        name: "email",
        label: "Email address",
        type: "email",
        autocomplete: "email",
        required: true,
        placeholder: "jordan@example.com"
      },
      {
        id: "phone",
        name: "phone",
        label: "Phone number",
        type: "tel",
        autocomplete: "tel",
        required: false,
        inputMode: "tel",
        placeholder: "+1 (555) 123-4567",
        helperText: "Optional. Use a format like +1 (555) 123-4567."
      }
    ];

    function Brand() {
      return `
        <a class="brand" href="#" aria-label="NovaDesk home">
          <span class="brand-badge" aria-hidden="true">N</span>
          <span>NovaDesk</span>
        </a>
      `;
    }

    function Header() {
      return `
        <header class="site-header">
          ${Brand()}
          <nav class="header-nav" aria-label="Primary">
            <ul>
              <li><a href="#">Product</a></li>
              <li><a href="#">Docs</a></li>
              <li><a href="#" aria-current="page">Support</a></li>
            </ul>
          </nav>
        </header>
      `;
    }

    function HeroPanel() {
      return `
        <section class="panel hero-panel" aria-labelledby="support-title">
          <div>
            <div class="eyebrow">
              <span aria-hidden="true">●</span>
              <span>Support contact</span>
            </div>
            <h1 id="support-title">Talk to our support team.</h1>
            <p>
              Send your details and we will follow up with the right specialist for account,
              billing, or technical questions.
            </p>
          </div>
          <div class="highlights" aria-label="Support benefits">
            <div class="highlight-card">
              <strong>Fast routing</strong>
              <span>Requests are sent to the team best suited to help.</span>
            </div>
            <div class="highlight-card">
              <strong>Personal follow-up</strong>
              <span>We reply using the email address you provide.</span>
            </div>
            <div class="highlight-card">
              <strong>Optional callback</strong>
              <span>Add a phone number if you want us to contact you by phone.</span>
            </div>
          </div>
        </section>
      `;
    }

    function Field({ id, name, label, type, autocomplete, required, placeholder, helperText, inputMode }) {
      const helperId = helperText ? `${id}-help` : "";
      const describedBy = helperId ? ` aria-describedby="${helperId}"` : "";
      const requiredMarker = required
        ? ` <span class="required-indicator" aria-hidden="true">*</span>`
        : "";

      return `
        <div class="form-field">
          <label for="${id}">${label}${requiredMarker}</label>
          <input
            id="${id}"
            name="${name}"
            type="${type}"
            autocomplete="${autocomplete}"
            ${required ? "required" : ""}
            ${inputMode ? `inputmode="${inputMode}"` : ""}
            placeholder="${placeholder}"
            ${describedBy}
          >
          ${helperText ? `<p class="helper-text" id="${helperId}">${helperText}</p>` : ""}
          <p class="error-text" id="${id}-error" hidden></p>
        </div>
      `;
    }

    function ContactForm() {
      return `
        <section class="panel form-panel" aria-labelledby="contact-form-title">
          <div class="card-header">
            <h2 id="contact-form-title">Send a request</h2>
            <p>Fields marked with <span aria-hidden="true">*</span> are required.</p>
            <p class="required-note">We only ask for the information needed to respond.</p>
          </div>
          <form id="support-form" novalidate>
            ${fields.map(Field).join("")}
            <p class="form-status" id="form-status" aria-live="polite"></p>
            <button class="submit-button" type="submit">Send request</button>
          </form>
        </section>
      `;
    }

    function Footer() {
      return `
        <footer class="site-footer">
          <p>Built for product support that feels fast, clear, and human.</p>
          <nav class="footer-nav" aria-label="Footer">
            <ul>
              <li><a href="#">Privacy</a></li>
              <li><a href="#">System status</a></li>
            </ul>
          </nav>
        </footer>
      `;
    }

    function App() {
      return `
        <a class="skip-link" href="#maincontent">Skip to main content</a>
        <div class="site-shell">
          ${Header()}
          <main id="maincontent" tabindex="-1">
            <div class="hero-grid">
              ${HeroPanel()}
              ${ContactForm()}
            </div>
          </main>
          ${Footer()}
        </div>
      `;
    }

    document.getElementById("app").innerHTML = App();

    const form = document.getElementById("support-form");
    const status = document.getElementById("form-status");
    let submissionAttempted = false;

    function getFieldById(id) {
      return document.getElementById(id);
    }

    function setFieldError(field, message) {
      const error = getFieldById(`${field.id}-error`);
      const helper = field.id === "phone" ? `${field.id}-help` : "";
      if (message) {
        field.setAttribute("aria-invalid", "true");
        field.setAttribute(
          "aria-describedby",
          helper ? `${helper} ${error.id}` : error.id
        );
        error.textContent = `Error: ${message}`;
        error.hidden = false;
        return false;
      }

      field.removeAttribute("aria-invalid");
      if (helper) {
        field.setAttribute("aria-describedby", helper);
      } else {
        field.removeAttribute("aria-describedby");
      }
      error.textContent = "";
      error.hidden = true;
      return true;
    }

    function validateField(field) {
      const value = field.value.trim();

      if (field.id === "fullName" && !value) {
        return setFieldError(field, "Enter your full name.");
      }

      if (field.id === "email") {
        if (!value) {
          return setFieldError(field, "Enter your email address.");
        }
        const isEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
        if (!isEmail) {
          return setFieldError(field, "Enter a valid email address, such as name@example.com.");
        }
      }

      if (field.id === "phone" && value) {
        const isPhone = /^\+?[0-9\s().-]{7,}$/.test(value);
        if (!isPhone) {
          return setFieldError(field, "Use a phone number format like +1 (555) 123-4567.");
        }
      }

      return setFieldError(field, "");
    }

    form.addEventListener("submit", (event) => {
      submissionAttempted = true;
      const invalidFields = fields
        .map(({ id }) => getFieldById(id))
        .filter((field) => !validateField(field));

      if (invalidFields.length > 0) {
        event.preventDefault();
        status.textContent = "Please review the highlighted fields and try again.";
        invalidFields[0].focus();
        return;
      }

      event.preventDefault();
      status.textContent = "Thanks. Your support request is ready to send.";
      form.reset();
      fields.forEach(({ id }) => setFieldError(getFieldById(id), ""));
      getFieldById("fullName").focus();
    });

    fields.forEach(({ id }) => {
      const field = getFieldById(id);
      field.addEventListener("blur", () => {
        if (submissionAttempted) {
          validateField(field);
        }
      });
      field.addEventListener("input", () => {
        if (submissionAttempted) {
          validateField(field);
        }
      });
    });
  </script>
</body>
</html>
