    function HeroPanel() {
      return `
        <section class="panel hero-panel" id="support-overview" aria-labelledby="support-title">
          <div>
            <div class="eyebrow">
              <span aria-hidden="true">●</span>
              <span>Support contact</span>
            </div>
            <h1 id="support-title">Talk to our support team.</h1>
            <p>
              Send your details and we will follow up with the right specialist for account,
              billing, or technical questions.
            </p>
          </div>
          <div class="highlights" aria-label="Support benefits">
            <div class="highlight-card">
              <strong>Fast routing</strong>
              <span>Requests are sent to the team best suited to help.</span>
            </div>
            <div class="highlight-card">
              <strong>Personal follow-up</strong>
              <span>We reply using the email address you provide.</span>
            </div>
            <div class="highlight-card">
              <strong>Optional callback</strong>
              <span>Add a phone number if you want us to contact you by phone.</span>
            </div>
          </div>
        </section>
      `;
    }

    function Field({ id, name, label, type, autocomplete, required, placeholder, helperText, inputMode }) {
      const helperId = helperText ? `${id}-help` : "";
      const describedBy = helperId ? ` aria-describedby="${helperId}"` : "";
      const requiredMarker = required
        ? ` <span class="required-indicator" aria-hidden="true">*</span>`
        : "";

      return `
        <div class="form-field">
          <label for="${id}">${label}${requiredMarker}</label>
          <input
            id="${id}"
            name="${name}"
            type="${type}"
            autocomplete="${autocomplete}"
            ${required ? "required" : ""}
            ${inputMode ? `inputmode="${inputMode}"` : ""}
            placeholder="${placeholder}"
            ${describedBy}
          >
          ${helperText ? `<p class="helper-text" id="${helperId}">${helperText}</p>` : ""}
          <p class="error-text" id="${id}-error" hidden></p>
        </div>
      `;
    }

    function ContactForm() {
      return `
        <section class="panel form-panel" aria-labelledby="contact-form-title">
          <div class="card-header">
            <h2 id="contact-form-title">Send a request</h2>
            <p>Fields marked with <span aria-hidden="true">*</span> are required.</p>
