      } else {
        field.removeAttribute("aria-describedby");
      }
      error.textContent = "";
      error.hidden = true;
      return true;
    }

    function validateField(field) {
      const value = field.value.trim();

      if (field.id === "fullName" && !value) {
        return setFieldError(field, "Enter your full name.");
      }

      if (field.id === "email") {
        if (!value) {
          return setFieldError(field, "Enter your email address.");
        }
        const isEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
        if (!isEmail) {
          return setFieldError(field, "Enter a valid email address, such as name@example.com.");
        }
      }

      if (field.id === "phone" && value) {
        const isPhone = /^\+?[0-9\s().-]{7,}$/.test(value);
        if (!isPhone) {
          return setFieldError(field, "Use a phone number format like +1 (555) 123-4567.");
        }
      }

      return setFieldError(field, "");
    }

